#!/usr/bin/env python3
"""Bounded best-effort FP challenge: reject lexical-miss-as-FP and classify non-predictive prose."""
import json,re,collections
from pathlib import Path
P=Path('/mnt/data');O=P/'oriondesk_phase4_v61';S3=P/'oriondesk_phase3_v61_redo';G2=P/'oriondesk_phase2_current_scored_8'
R=lambda x:[json.loads(s) for s in open(x) if s.strip()]
W=lambda x,r:(O/x).write_text(''.join(json.dumps(a,ensure_ascii=False)+'\n' for a in r),encoding='utf8')
V=R(O/'04_generated_claim_validity_final.jsonl');G=R(G2/'02_generated_classes_final.jsonl');GO=R(G2/'02_generated_atoms_final.jsonl');S=R(S3/'01_source_atoms_final.jsonl');N=R(S3/'01_source_negative_controls_final.jsonl');M=R(S3/'03_evidence_matches_final.jsonl');GS={g['generated_id']:g for g in GO}
