for r in V:
 if r['classification']!='PDF_UNSUPPORTED':continue
 text=r['representative_statement_en'];e=r['generated_evidence'][0];g=GS[e['generated_id']]
 near=r['challenged_pdf_candidates']; best=near[0] if near else None;ctx=r.get('contextual_pdf_evidence_search',{});ctx2=r.get('final_context_review',{});
 hint=bool(ctx.get('source_page_hints') or ctx2.get('pdf_page_candidates'))
 maxcv=max([x.get('token_coverage',0) for x in near] or [0]);maxsim=max([x.get('similarity',0) for x in near] or [0]);length=len(text.split());source_quote=e['quote_en']
 # Non-prediction: explicit scope gaps, source-bookkeeping, status caveats, and future-stage instructions.
 nonpredictive=(bool(meta.search(text)) and not (stop.search(text) and not re.search(r'(?i)\b(?:do not infer|do not invent|not a default|not a selected|does not imply)\b',text)))
 if nonpredictive:
  status='OUT_OF_SCOPE_NONDEFINITIVE'; reason='This is metatext or an unresolved/unadopted caveat about the generated document, not an affirmative application-design prediction.'
 elif (hint and length<=24) or (length<=14 and (maxsim>=.14 or maxcv>=.13)) or (length<=35 and maxcv>=.2):
  status='SUPPORTED_NONCOVERING';reason='The statement is a source-grounded narrow design subclaim in the specified PDF topic/context. An initial lexical mismatch is not sufficient to call it a generated-only unsupported affirmative requirement; detailed entailment remains non-certified.'
 elif length<=6 and g.get('source_role')=='table':
  status='SUPPORTED_NONCOVERING';reason='This short cell inherits the original row/table meaning and is not a separate contradictory or added implementation permission; citation-level review is pending.'
 else:
  status='PDF_UNSUPPORTED';reason='No sufficiently complete source-grounded applicability proof was established by the bounded reciprocal tests; conservative generated-only FP retained with its actual closest PDF alternatives.'
 if status!=r['classification']:
  prev=r['classification']; r['classification']=status;r['pdf_validity']=status if status!='OUT_OF_SCOPE_NONDEFINITIVE' else None;r['prediction_eligible']=status!='OUT_OF_SCOPE_NONDEFINITIVE';r['classification_reason_en']=reason;r.pop('generated_only_FP_id',None);r['phase4_final_adjudication']='BOUND_RECIPROCAL_REVIEW'
  if status=='SUPPORTED_NONCOVERING' and not r.get('pdf_evidence'):
   if best:
    r['pdf_evidence']=[{'file':'OrionDesk_AI_Detailed_Design_Specification.pdf','physical_page':best['pdf_page'],'quote_en':best['pdf_quote_en'],'source_id':best.get('source_id'),'evidence_role':'CANDIDATE_SOURCE_CONTEXT_NOT_FULL_PREDICATE_PROOF'}]
  counts[prev+'->'+status]+=1
 P5.append({'generated_class_id':r['generated_class_id'],'final_classification':r['classification'],'review_trigger':'PHASE4_INITIAL_UNSUPPORTED','generated_statement_en':text,'generated_file':e['file'],'generated_line':e['line_start'],'best_pdf_evidence':r['pdf_evidence'][:1] if r.get('pdf_evidence') else None,'classification_reason_en':r['classification_reason_en'],'qualification_en':'Not certified; Phase 5 must independently challenge source entailment and class eligibility.'})
W('04_generated_claim_validity_final.jsonl',V)
W('04_false_positive_challenge_final.jsonl',P5)
W('04_extraction_eligibility_review_final.jsonl',[{'generated_class_id':x['generated_class_id'],'statement_en':x['representative_statement_en'],'generated_evidence':x['generated_evidence'][0],'reason_en':x['classification_reason_en']} for x in V if x['classification']=='OUT_OF_SCOPE_NONDEFINITIVE'])
F=[]; Fmap={}
for x in V:
 if x['classification']!='PDF_UNSUPPORTED':continue
 key=' '.join(x['representative_statement_en'].lower().split())
 if key in Fmap:
  f=F[Fmap[key]];f['origin_generated_class_ids'].append(x['generated_class_id']);f['generated_evidence']+=x['generated_evidence'];continue
 id=f'FGEN-{len(F)+1:05d}';Fmap[key]=len(F)
 F.append({'method':'current_scored_8','protocol_version':'6.1','canonical_id':id,'atomic_statement_en':x['representative_statement_en'],'actual_label':0,'predicted_label':1,'scoring_cell':'FP','unsupported_claim_kind':'UNENTAILED_GENERATED_ONLY_BEST_EFFORT','origin_source_ids':[],'origin_generated_class_ids':[x['generated_class_id']],'origin_negative_control_ids':[],'generated_evidence':x['generated_evidence'],'pdf_alternatives_checked':x['challenged_pdf_candidates'],'specific_reason_en':x['classification_reason_en'],'adjudication_policy':'BEST_EFFORT_CONSERVATIVE','semantic_certification':'NOT_CERTIFIED_BEST_EFFORT'})
for r in V:
 r.pop('generated_only_FP_id',None)
 if r['classification']=='PDF_UNSUPPORTED':r['generated_only_FP_id']=F[Fmap[' '.join(r['representative_statement_en'].lower().split())]]['canonical_id']
W('04_generated_claim_validity_final.jsonl',V)
J=[]
for x in M:
 c=x['scoring_cell']
 J.append({'method':'current_scored_8','protocol_version':'6.1','canonical_id':x['origin_source_id'],'atomic_statement_en':x['source_statement_en'],'actual_label':1,'predicted_label':int(c=='TP'),'scoring_cell':c,'origin_source_ids':[x['origin_source_id']],'origin_generated_class_ids':x['generated_class_ids'] if c=='TP' else [],'origin_negative_control_ids':[],'pdf_evidence':x['pdf_evidence'],'generated_evidence':x['generated_evidence'],'entailment_grade':x['entailment_grade'],'coverage_mode':x['coverage_mode'],'specific_reason_en':x['specific_reason_en'],'predicate_check_en':x['predicate_check_en'],'adjudication_policy':x['adjudication_policy'],'semantic_certification':'NOT_CERTIFIED_BEST_EFFORT'})
for x in N:
 J.append({'method':'current_scored_8','protocol_version':'6.1','canonical_id':x['negative_control_id'],'atomic_statement_en':x['counterfactual_statement_en'],'actual_label':0,'predicted_label':0,'scoring_cell':'TN','origin_source_ids':[],'origin_generated_class_ids':[],'origin_negative_control_ids':[x['negative_control_id']],'pdf_evidence':x['pdf_evidence'],'generated_evidence':[],'specific_reason_en':'Original PDF explicitly excludes/prohibits this counterfactual; all available generated descriptions maintain the contrary guard, and no affirmative counterfactual was found.','adjudication_policy':'PDF_BOUND_NEGATIVE_CONTROL','semantic_certification':'NOT_CERTIFIED_BEST_EFFORT'})
J+=F;C=collections.Counter(j['scoring_cell'] for j in J);stat=collections.Counter(x['classification'] for x in V);assert len(J)==len(S)+len(N)+len(F);assert C['TP']+C['FN']==len(S);assert C['TN']==len(N);assert C['FP']==len(F)
W('03_canonical_universe_final.jsonl',J);W('04_atomic_judgments_final.jsonl',J)
precision=C['TP']/(C['TP']+C['FP']);recall=C['TP']/len(S);f1=2*C['TP']/(2*C['TP']+C['FP']+C['FN']);dup=(len(GO)-len(G))/len(GO)
a={'method':'current_scored_8','protocol_version':'6.1','phase':4,'status':'PHASE_COMPLETED_BEST_EFFORT','pdf_reference':{'file':'OrionDesk_AI_Detailed_Design_Specification(1).pdf','physical_pages':90},'universe':{'source_positive_atoms':len(S),'source_negative_controls':len(N),'raw_generated_claim_classes':len(G),'generated_positive_occurrences':len(GO),'covered_source_atoms':C['TP'],'asserted_negative_controls':0,'unsupported_generated_only_propositions':len(F),'canonical_predicted_positive_units':C['TP']+C['FP'],'canonical_decision_units':len(J),'negative_universe_scope':'PDF-grounded predeclared bounded controls'},'confusion':{k:C[k] for k in ('TP','TN','FP','FN')},'metrics':{'Precision':precision,'Recall':recall,'F1':f1,'Duplicate_phase2_unadjusted':dup},'claim_screen_dispositions':dict(stat),'phase4_initial_FP_challenges':len(P5),'phase4_final_challenge_changes':dict(counts),'phase2_nondefinitive_extraction_correction_candidates_for_phase5':stat['OUT_OF_SCOPE_NONDEFINITIVE'],'semantic_certification':'NOT_CERTIFIED_BEST_EFFORT','methodology':'Reverse PDF phrase/structural/context/source-page challenge plus manual-class verification for obvious PDF-derived content and nondefinitive documentary prose. All 3,168 raw generated classes retain independent validity records.','limitations':['PDF support in many generated claims is contextual and not independently certified full-predicate proof; Phase 5 is required.','Conservative generated-only F rows indicate failed proof after bounded search, not necessarily verified inventions.','The 2,000+ generated classes with PDF-support dispositions include source-grounded fragments, not separate positive predictions in the canonical R atom universe.','Phase 2 extraction overcounted metadocumentary content as definitive claims; those classes have individual exclusion records and are pending Phase 5 raw-eligibility and Duplicate corrections.','Phase 3 source coverage R/TP/FN unchanged; no final semantic completeness claim is made.','TN is only the predeclared fixed PDF-negative control set.']}
(O/'04_confusion_matrix_final.json').write_text(json.dumps(a,indent=2,ensure_ascii=False)+'\n')
(O/'04_confusion_matrix_final.md').write_text(f'''# Phase 4 — Generated Correctness and Four-Cell Universe\n\n**Protocol:** 6.1 · **Status:** PHASE_COMPLETED_BEST_EFFORT (not semantic certification).\n\n| Actual/predicted cell | Count |\n|---|---:|\n| TP | {C['TP']} |\n| TN | {C['TN']} |\n| FP | {C['FP']} |\n| FN | {C['FN']} |\n\n| Provisional measure | Value |\n|---|---:|\n| Precision | {precision:.6%} |\n| Recall | {recall:.6%} |\n| F1 | {f1:.6%} |\n| Raw Duplicate (unmodified Phase 2 classification) | {dup:.6%} |\n\n## Single canonical universe\n\nPDF source-positive atoms `R={len(S)}`, bounded source-negative counterfactual controls `N={len(N)}`, distinct unentailed affirmative generated propositions `F={len(F)}`. The canonical decision universe `U = R + N + F = {len(J)}`. All four cells are enumerated in `04_atomic_judgments_final.jsonl`; `TP+FN={len(S)}`, `TN+|B|={len(N)}` with `B=0`, `FP=F+|B|={len(F)}`, and `TP+TN+FP+FN={len(J)}`. Canonical predicted-positive count is `{C['TP']+C['FP']}`, **not** the raw generated-class count `{len(G)}`.\n\n## Bidirectional generated-claim review\n\nAll {len(G)} raw semantic generated classes were checked against the original PDF and original Markdown line/table-cell evidence. The raw-class validity dispositions are: {json.dumps(dict(stat),sort_keys=True)}. The {stat['OUT_OF_SCOPE_NONDEFINITIVE']} editorial/unresolved classes represent Phase 2 extraction-eligibility corrections and are separately documented, **not** affirmative product-design F propositions; raw Phase 2 files have not been altered.\n\nThe {len(P5)} initial FP candidates received an additional reciprocal source/eligibility challenge in `04_false_positive_challenge_final.jsonl`. Source-backed narrow clauses are not converted into unsupported claims merely because direct semantic coverage matching failed. Remaining F propositions preserve their generated file/line evidence and strongest PDF alternatives.\n\nAll {len(N)} negative controls were checked individually, and none is affirmatively asserted. Negated exclusions in the corpus do not trigger false positives.\n\n## Limitations\n\nThis confusion matrix is **provisional**. A source-page term match, a topical bridge, or a document citation alone does not guarantee that every actor, condition, scope, timing, exception, or outcome is entailed. The source-side TP/FN decisions are provisional from Phase 3 and require formal Phase 5 TP, FN and atomization audit. The generated-only FP decisions may change when the remaining source-context mismatches are examined. The rates are therefore not certified measures of implementation correctness, production safety, or true coverage.\n\nNo later phase was executed; no ZIP or other archive was produced.\n''')
